package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import java.util.*;import org.springframework.util.function.ThrowingSupplier;
/** Genuine formal preparation feeds the original 081 atomic binding producer. It never creates a score or qualification. */
public final class FormalEvaluationScoreBindingService {
 private final EnterpriseAccess access;private final FormalAgentAcceptanceEvidence evidence;private final FormalEvaluationScoreBindingSchema schema;private final FormalAgentPublicationSchema json;private final ExpertQualificationService experts;private final ExpertQualificationStore store;private final ExpertQualificationAuthority authority;
 public FormalEvaluationScoreBindingService(EnterpriseAccess access,FormalAgentAcceptanceEvidence evidence,FormalEvaluationScoreBindingSchema schema,FormalAgentPublicationSchema json,ExpertQualificationService experts,ExpertQualificationStore store,ExpertQualificationAuthority authority){this.access=access;this.evidence=evidence;this.schema=schema;this.json=json;this.experts=experts;this.store=store;this.authority=authority;}
 public JsonNode bind(ApplicationSessionIdentity.Verified subject,String context,String key,byte[] bytes)throws Exception{
  JsonNode outer=schema.request(bytes).deepCopy();ExpertQualificationSchema.key(key);var prior=access.execute(subject,a->checked(()->{current(a,context);return original(a,key,outer);}));if(prior!=null)return recover(subject,context,key,outer);
  var prepared=evidence.prepareScoreBinding(subject,context,outer);return access.execute(subject,a->checked(()->{current(a,context);var permit=evidence.requireScoreBinding(a,outer,prepared);var receipt=experts.bindScoreFormal(a,subject,context,key,outer.required("binding"),permit);var saved=original(a,key,outer);if(saved==null||!json.canonical(receipt).equals(saved.receiptJson()))bad();return response(key,outer,receipt);}));
 }
 /** Read-only original-key reconciliation: no operation, score, grant, binding or cancellation is written. */
 public JsonNode recover(ApplicationSessionIdentity.Verified subject,String context,String key,JsonNode outer)throws Exception{
  schema.validate(outer);ExpertQualificationSchema.key(key);var first=access.execute(subject,a->checked(()->{current(a,context);var row=original(a,key,outer);if(row==null)throw new TenantAccessException(ErrorCode.OBJECT_UNAVAILABLE);return row;}));
  var prepared=evidence.prepareScoreBindingRead(subject,context,outer);return access.execute(subject,a->checked(()->{current(a,context);var row=original(a,key,outer);if(row==null||!row.equals(first))throw new TenantAccessException(ErrorCode.SCOPE_STALE);var read=evidence.requireScoreBindingRead(a,outer,prepared);var snapshot=read.requireConsumer(a,outer.required("binding"));authority.requireQualifiedScore(a,new PermissionProtocol.Basis(row.recordId(),row.contentHash()),snapshot).requireUnchanged();return response(key,outer,store.parse(row.receiptJson()));}));
 }
 private ExpertQualificationProtocol.Journal original(EnterpriseAccess.Admission a,String key,JsonNode outer)throws Exception{
  var row=store.prior(a,"SCORE_BIND",key,outer.required("binding"));if(row==null)return null;if(!a.actorId().equals(row.createdBy())||!key.equals(row.idempotencyKey()))deny();var witness=store.parse(row.authorizationsJson()).get("formal_preparation");if(witness==null||!witness.isObject()||witness.size()!=7)bad();if(!"1.0.0".equals(witness.path("schema_version").asText())||!witness.path("request_body_sha256").asText().equals(json.hash(outer))||!json.canonical(witness.required("request")).equals(json.canonical(outer))||!json.canonical(witness.required("statistics_policy")).equals(json.canonical(outer.required("statistics_policy")))||!witness.path("definition_sha256").asText().equals(outer.required("evaluation").required("content_sha256").asText()))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);if(!witness.required("policy_authorizations").isObject()||!witness.required("execution_authorizations").isObject())bad();return row;
 }
 private JsonNode response(String key,JsonNode outer,JsonNode receipt)throws Exception{var result=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("original_key",key).put("request_body_sha256",json.hash(outer));result.set("receipt",receipt.deepCopy());return schema.receipt(result);}
 private static void current(EnterpriseAccess.Admission a,String context){PermissionSchema.revision(context);if(!a.context().context_revision().equals(context))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);}private static <T>T checked(ThrowingSupplier<T> s){return s.get();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
